import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"53、【渐】 艮下巽上","description":"周易尚氏学 - 53、【渐】 艮下巽上","frontmatter":{"title":"53、【渐】 艮下巽上","description":"周易尚氏学 - 53、【渐】 艮下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/058.md","filePath":"zh/classics/shangshi/058.md"}'),s={name:"zh/classics/shangshi/058.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_53、【渐】-艮下巽上" tabindex="-1">53、【渐】 艮下巽上 <a class="header-anchor" href="#_53、【渐】-艮下巽上" aria-label="Permalink to “53、【渐】 艮下巽上”">​</a></h1><p>上下卦皆阴承阳。阴承阳即妇从夫。故曰日渐。渐进也。次也。言阴次于是。宜进而承阳也。巽为妇。艮止于下。有女归之象。二五应。故利贞而吉。</p><p>彖曰。渐之进也。女归吉也。进得位。往有功也。进以正。可以正邦也。其位。刚得中也。止而巽。动不穷也。</p><p>五得位故有功。艮为邦。故曰正邦。</p><p>象曰。山上有木。渐。君子以居贤德善俗。</p><p>居积也。居贤德。即积贤德也。坎为积。艮为贤。巽为风俗。有贤德故以善俗。居贤德善俗。皆非猝然可能之事。皆渐义也。</p><p>初六。鸿渐于乾。小子厉。有言。无咎。</p><p>鸿大雁也。艮为鸿。周公时训。以雁北乡当屯卦。是以坎为北。互艮为雁。故易林师之萃云。鸿雁哑哑。以水为家。以萃互艮为鸿也。需之遁云。去如飞鸿。亦以遁下艮为鸿。千水涯也。二至四坎水。初在坎下。故曰鸿渐于乾。艮少故为小子。有言者争讼。震为言。艮为反震。败言。故曰有言。左传云。败言为谗是也。有言故厉。然初为士。潜伏在下。亦无咎也。</p><h3 id="象曰。小子之厉。义无咎也。" tabindex="-1">象曰。小子之厉。义无咎也。 <a class="header-anchor" href="#象曰。小子之厉。义无咎也。" aria-label="Permalink to “象曰。小子之厉。义无咎也。”">​</a></h3><p>初勿用。故义无咎。</p><p>六二。鸿渐于磐，饮食衎衎，吉。</p><p>盘大石也。三艮为石。故渐于盘。二坎体。坎为饮食。衎衎。和乐也。二当位得中应五。故象吉如是。</p><h3 id="象曰。饮食衎衎。不素饱也。" tabindex="-1">象曰。饮食衎衎。不素饱也。 <a class="header-anchor" href="#象曰。饮食衎衎。不素饱也。" aria-label="Permalink to “象曰。饮食衎衎。不素饱也。”">​</a></h3><p>坎中实为饱。应在五。巽为白。故曰素饱。素饱犹素餐。不素饱。言得之以道也。</p><p>九三。鸿渐于陆。夫征不复。妇孕不育。凶。利御寇。</p><p>马云。山上高平曰陆。艮为夫。在上。故不复。易林复之剥云。夫亡从军。抱膝独宿。以剥艮为夫也。孕。妊娠也。育生也。震为孕。左传昭元年。武王邑姜。方震太叔是也。三震覆。故不育。郭璞洞林否之小过云。妇女胎反见华益。否三互巽。故知为妇女。二四互艮。世变良。艮为反震。是胎反也。胎亦孕也。义即本此也。巽为寇。三下拥群阴。而艮为守御。为坚。寇在外。守御在内。使外寇不人。故利也。旧解皆以坎为寇。岂知坎之为寇。以其隐伏。巽亦为伏。故易亦以巽为寇。且以坎为寇。坎寇已在内矣。如何能御之。虞翻以坎为寇。谓自上御下。自上御下。其利在上。于三何与。一象失传。使经义颠倒错乱。至于如此。真可喂也。</p><h3 id="象曰。夫征不复。离群五也。妇孕不育。失其道出。利用御冠。顺相保也。" tabindex="-1">象曰。夫征不复。离群五也。妇孕不育。失其道出。利用御冠。顺相保也。 <a class="header-anchor" href="#象曰。夫征不复。离群五也。妇孕不育。失其道出。利用御冠。顺相保也。" aria-label="Permalink to “象曰。夫征不复。离群五也。妇孕不育。失其道出。利用御冠。顺相保也。”">​</a></h3><p>坤为众为丑，丑众也。诗小雅。执讯获五是也。高附离也。群丑谓下二阴。言三阳系恋于下二阴。故不复也。诸家训离为去。与下顺相保之义不合。非也。艮为道。坎为失。故失道不育。下二阴顺三阳。以为保守。故曰顺相保。</p><p>六四。鸿渐于木。或得其桷。无咎。</p><p>巽为鸿。九家逸象巽为鹳。鹳鸿皆水鸟。故亦为鸿。周公时训以鸿雁来当巽卦。是以巽为鸿。故易林中孚之同人云。鸿飞遵陆。以同人互巽为鸿。又大畜之兑云。鸿盗我襦。逃于山隅。兑互巽为盗为鸿。旧以离为鸿非也。巽为木为桷。说文椽方曰桷。得桷言安也。四当位承阳。故无咎。</p><h3 id="象曰。或得其桷。顺以巽也。言顺承五上二阳。" tabindex="-1">象曰。或得其桷。顺以巽也。言顺承五上二阳。 <a class="header-anchor" href="#象曰。或得其桷。顺以巽也。言顺承五上二阳。" aria-label="Permalink to “象曰。或得其桷。顺以巽也。言顺承五上二阳。”">​</a></h3><p>九五。鸿渐于陵。妇三岁不孕。终莫之胜。吉。</p><p>巽为高。五应在二。二艮体。五居艮上。故渐于陵。巽为妇。震为孕。震伏。下敝漏。故不孕。又五应在二。为三所阻。不能应二。故三岁不孕。坎为三岁。言其久。然五与二为正应。三岂能终阻之。故终胜三。得所愿而吉也。莫之胜。言三不能胜五也。</p><h3 id="象曰。终莫之胜吉。得所愿也。" tabindex="-1">象曰。终莫之胜吉。得所愿也。 <a class="header-anchor" href="#象曰。终莫之胜吉。得所愿也。" aria-label="Permalink to “象曰。终莫之胜吉。得所愿也。”">​</a></h3><p>五终能应二。故得所愿。旧解皆从虞氏以成既济定为说。强命初上变。非。</p><p>上九。鸿渐于陆。其羽可用为仪。吉。</p><p>在卦上。与三同。故仍渐于陆。巽为羽。仪饰也。其羽可用为仪者。巽为高为白。言上居高明之地。羽毛鲜洁。故可用以为仪。贲一切也。巽羽之象。易林随之小畜云。奋翅鼓翼。以小畜上巽为翼。又颐之兑六翮长翼。亦以兑互类为翼。</p><h3 id="象曰。其羽可用为仪吉。不可乱也。" tabindex="-1">象曰。其羽可用为仪吉。不可乱也。 <a class="header-anchor" href="#象曰。其羽可用为仪吉。不可乱也。" aria-label="Permalink to “象曰。其羽可用为仪吉。不可乱也。”">​</a></h3><p>仪型万方。秩然不紊。故不可乱。</p>',29)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
